"""CARLA-lazy, source-bound reverse-crosswalk capture for C215286.

The site packet and documents are materialized with the exact construction.
This runner attempts motion and retains original sources; it makes no legal or
physical-acceptance claim.
"""
import argparse
import json
import math
from contextlib import ExitStack
from pathlib import Path
from queue import Empty,Queue

from camera_encoder import FFV1Writer
from camera_setup import PROFILE,source_cameras
from reverse_control import reverse_vehicle
from reverse_route import ReverseTargetController,prepare_reviewed_pair

ASSIGNMENT='testing__C215286__NRS-484B-113-2__motor_vehicle_driver'
OVER=ASSIGNMENT+'__reverse_over_crosswalk'
SHORT=ASSIGNMENT+'__reverse_stops_before_crosswalk'
CAMERAS=tuple(PROFILE)


def validate_config(config):
 if config.get('law_id')!='NRS-484B-113-2' or config.get('cell_id')!='C215286' or config.get('actor')!='motor_vehicle_driver':
  raise ValueError('Exact C215286 law/cell/actor required')
 if config.get('selected_case_id') not in (OVER,SHORT):raise ValueError('Exact reverse case required')
 if set(config.get('supported_case_ids',[]))!={OVER,SHORT}:raise ValueError('Both exact reverse cases required')
 if config.get('rate_hz')!=20 or config.get('duration_s')!=45:
  raise ValueError('Pinned 20 Hz and 45-second capture required')
 cameras=config.get('cameras')
 if not isinstance(cameras,list) or [r.get('name') for r in cameras]!=list(CAMERAS):
  raise ValueError('Four ordered source cameras required')
 if any((r.get('width'),r.get('height'))!=PROFILE[r['name']] or
        type(r.get('fov_deg')) not in (int,float) or not 30<=r['fov_deg']<=120
        for r in cameras):raise ValueError('Pinned camera size/FOV required')
 if not isinstance(config.get('required_atoms'),list):raise ValueError('Required atom inventory missing')
 if config.get('site_packet')!='site_packet.json':raise ValueError('Exact saved site packet required')
 return config


def prepare_site(packet,source_root,config):
 transform=packet.get('start_transform')
 if not isinstance(transform,dict):raise ValueError('Reviewed Native start transform required')
 for key in ('x','y','z','yaw_deg'):
  value=transform.get(key)
  if type(value) not in (int,float) or not math.isfinite(value):
   raise ValueError('Finite Native start transform required: '+key)
 forward=[math.cos(math.radians(transform['yaw_deg'])),math.sin(math.radians(transform['yaw_deg']))]
 body=packet.get('start_body_vertices_xy_m')
 if not isinstance(body,list) or len(body)<4:raise ValueError('Reviewed starting complete body required')
 distances=packet.get('target_distances_m')
 if not isinstance(distances,dict):raise ValueError('Both reverse target distances required')
 prepared=prepare_reviewed_pair(packet,source_root,body,forward,
                                over_distance_m=distances.get('over'),
                                short_distance_m=distances.get('short'),
                                native_map_id=packet.get('native_map_id'),
                                road_id=packet.get('road_id'),
                                crosswalk_id=packet.get('crosswalk_id'))
 selected=distances['over' if config['selected_case_id']==OVER else 'short']
 return prepared,transform,forward,float(selected)


def _body(actor):
 transform=actor.get_transform()
 vertices=actor.bounding_box.get_world_vertices(transform)
 points=[[float(v.x),float(v.y)] for v in vertices]
 if len(points)<4 or any(not all(math.isfinite(c) for c in p) for p in points):
  raise ValueError('Incomplete original Native complete body')
 return points


def _center(points):
 return [(min(p[i] for p in points)+max(p[i] for p in points))/2 for i in (0,1)]


def _record(actor,snapshot,packet):
 transform=actor.get_transform();velocity=actor.get_velocity()
 yaw=float(transform.rotation.yaw)
 if not math.isfinite(yaw):raise ValueError('Nonfinite Native heading')
 body=_body(actor);forward=[math.cos(math.radians(yaw)),math.sin(math.radians(yaw))]
 values=[float(velocity.x),float(velocity.y)]
 if not all(math.isfinite(v) for v in values):raise ValueError('Nonfinite Native velocity')
 return {'frame':int(snapshot.frame),'time_s':float(snapshot.timestamp.elapsed_seconds),
         'road_id':packet['road_id'],'crosswalk_id':packet['crosswalk_id'],
         'native_reverse':bool(actor.get_control().reverse),
         'ego_forward_xy':forward,'ego_body_vertices_xy_m':body,
         'body_vertices_m':body,'heading_deg':yaw,'velocity_mps':values,
         'actor_id':int(actor.id)}


def _sensor_frame(queue,frame):
 for _ in range(6):
  try:image=queue.get(timeout=10)
  except Empty as error:raise ValueError('Source camera frame missing') from error
  if image.frame==frame:return image
  if image.frame>frame:raise ValueError('Source camera skipped Native frame')
 raise ValueError('Source camera frame join failed')


def _camera_transforms(carla,packet,transform):
 points=packet['crosswalk_polygon_xy_m']
 x=sum(p[0] for p in points)/len(points);y=sum(p[1] for p in points)/len(points)
 z=transform['z'];yaw=transform['yaw_deg']
 def pose(px,py,pz,heading,pitch):
  return carla.Transform(carla.Location(x=px,y=py,z=pz),carla.Rotation(yaw=heading,pitch=pitch))
 return {'overview':pose(x,y,z+42,yaw,-75),
         'approach':pose(transform['x']+10,transform['y'],z+6,yaw+180,-15),
         'reference_corner':pose(x+12,y+12,z+12,yaw-135,-30),
         'driver_reference':pose(1,0,1.65,180,-5)}


def capture(args,config):
 import carla
 from pipeline_capture import PipelineCapture
 from worker_exchange.native_output import FrameMap,seal_capture
 from worker_exchange.world_restore import snapshot as snapshot_world,restore
 output=Path(args.output_dir).resolve()
 if not output.is_dir() or not (output/'construction.json').is_file():
  raise ValueError('Use runtime.py capture to materialize exact construction first')
 packet=json.loads((output/'site_packet.json').read_text())
 prepared,start,forward,target=prepare_site(packet,output,config)
 client=carla.Client(args.host,args.port);client.set_timeout(30)
 saved=snapshot_world(client);world=client.get_world();actor=None;capture_helper=None
 encoders={};frames=0;error=None
 try:
  if world.get_map().name!=packet['native_map_id']:
   raise ValueError('Native map differs from reviewed site')
  settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05
  world.apply_settings(settings)
  location=carla.Location(x=start['x'],y=start['y'],z=start['z'])
  waypoint=world.get_map().get_waypoint(location,project_to_road=False)
  if waypoint is None or waypoint.road_id!=packet['road_id']:
   raise ValueError('Reviewed Native start is not on selected road')
  blueprint=world.get_blueprint_library().find(packet['vehicle_blueprint_id'])
  actor=world.try_spawn_actor(blueprint,carla.Transform(location,carla.Rotation(yaw=start['yaw_deg'])))
  if actor is None:raise ValueError('Native reverse vehicle spawn failed')
  actual_body=_body(actor)
  # The reviewed body is a planning footprint; the Native body must be checked
  # against both target geometries before any motion is attempted.
  actual=prepare_reviewed_pair(packet,output,actual_body,forward,
                               over_distance_m=packet['target_distances_m']['over'],
                               short_distance_m=packet['target_distances_m']['short'],
                               native_map_id=packet['native_map_id'],road_id=packet['road_id'],
                               crosswalk_id=packet['crosswalk_id'])
  (output/'crosswalk_context.json').write_text(json.dumps({
    'native_map_id':packet['native_map_id'],'road_id':packet['road_id'],
    'crosswalk_id':packet['crosswalk_id'],
    'crosswalk_geometry_source':packet['crosswalk_geometry_source']['path'],
    'crosswalk_camera_source':packet['crosswalk_marking_source']['path'],
    'reverse_route_source':'original Native vehicle body and paired target distances',
    'residence_district_source':packet['district_source']['path'],
    'crosswalk_polygon_xy_m':packet['crosswalk_polygon_xy_m'],
    'site_source_review':prepared['site_review'],
    'native_target_review':actual['targets']},indent=2)+'\n')
  origin=_center(actual_body)
  controller=ReverseTargetController(origin,forward,target)
  transforms=_camera_transforms(carla,packet,start)
  with reverse_vehicle(world,actor,carla.VehicleControl,throttle=.1):
   with source_cameras(world,actor,transforms,config['cameras']) as sensors:
    queues={name:Queue() for name in CAMERAS}
    for name,sensor in sensors.items():sensor.listen(lambda image,name=name:queues[name].put(image))
    with ExitStack() as stack:
     for name,(width,height) in PROFILE.items():
      encoders[name]=stack.enter_context(FFV1Writer(output/(name+'.mkv'),width,height))
     mapping=stack.enter_context(FrameMap(output/'video_frames.jsonl'))
     history=stack.enter_context((output/'reverse_history.jsonl').open('x',buffering=1))
     capture_helper=PipelineCapture(client,actor,output,config['selected_case_id'],
                                    required_observations=config['required_atoms'])
     try:
      for _ in range(config['duration_s']*config['rate_hz']):
       body=_body(actor);velocity=actor.get_velocity()
       speed=math.hypot(float(velocity.x),float(velocity.y))
       command=controller.step(_center(body),speed)
       actor.apply_control(carla.VehicleControl(throttle=command['throttle'],
                                                brake=command['brake'],reverse=True))
       world.tick();snapshot=world.get_snapshot()
       for name in CAMERAS:encoders[name].write(bytes(_sensor_frame(queues[name],snapshot.frame).raw_data))
       capture_helper.capture(snapshot.frame,snapshot.timestamp.elapsed_seconds)
       mapping.append(snapshot.frame,snapshot.timestamp.elapsed_seconds)
       history.write(json.dumps(_record(actor,snapshot,packet),separators=(',',':'))+'\n')
       frames+=1
     finally:
      capture_helper.close();capture_helper=None
 except BaseException as caught:
  error=caught;raise
 finally:
  cleanup=[]
  if capture_helper is not None:
   try:capture_helper.close(confirmed=False)
   except BaseException as caught:cleanup.append(str(caught))
  if actor is not None:
   try:actor.destroy()
   except BaseException as caught:cleanup.append(str(caught))
  restoration=restore(client,saved)
  if error is None and not cleanup:
   seal_capture(output,frames=frames,restoration=restoration,errors=[],
                encoder_exit_codes={name:e.exit_code for name,e in encoders.items()},
                context={'crosswalk_site_source_check':prepared['site_review'],
                         'physical_acceptance_claimed':False})
  if error is None and cleanup:raise ValueError('Native cleanup failed: '+'; '.join(cleanup))


def main():
 parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
 parser.add_argument('--output-dir');parser.add_argument('--host',default='127.0.0.1')
 parser.add_argument('--port',type=int,default=2000);args=parser.parse_args()
 config=validate_config(json.loads(Path(__file__).with_name('config.json').read_text()))
 if args.check:
  print(json.dumps({'case_id':config['selected_case_id'],'cpu_check_passed':True,'carla_started':False}))
  return
 if not args.output_dir:raise ValueError('--output-dir required for Native capture')
 capture(args,config)


if __name__=='__main__':main()

"""Four original RGB source cameras for C215286 reverse construction."""
from contextlib import contextmanager

PROFILE = {'overview': (1920, 1080), 'approach': (1280, 720),
           'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms, plan):
    rows = {row['name']: row for row in plan}
    if set(rows) != set(PROFILE) or set(transforms) != set(PROFILE):
        raise ValueError('All four named source cameras required')
    sensors = {}
    try:
        for name, size in PROFILE.items():
            row = rows[name]
            if (row.get('width'), row.get('height')) != size:
                raise ValueError('Pinned source camera dimensions required')
            fov = row.get('fov_deg')
            if type(fov) not in (int, float) or not 30 <= fov <= 120:
                raise ValueError('Source camera FOV required')
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            for key, value in [('image_size_x', size[0]), ('image_size_y', size[1]),
                               ('fov', fov), ('sensor_tick', 0.05)]:
                blueprint.set_attribute(key, str(value))
            kwargs = {'attach_to': ego} if name == 'driver_reference' else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError('Native camera spawn failed: ' + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Native reverse request and readback for a source-reviewed approach."""
from contextlib import contextmanager
@contextmanager
def reverse_vehicle(world,vehicle,control_factory,*,throttle=0.2):
 if not 0<throttle<=0.4:raise ValueError('Conservative reverse throttle required')
 original=vehicle.get_control()
 try:
  vehicle.apply_control(control_factory(throttle=throttle,brake=0.0,reverse=True))
  world.tick()
  if vehicle.get_control().reverse is not True:raise ValueError('Native reverse readback failed')
  yield vehicle
 finally:
  vehicle.apply_control(original)
  world.tick()
  if vehicle.get_control().reverse!=original.reverse:raise ValueError('Vehicle control restoration failed')

"""Straight Native reverse targets for matched crosswalk comparisons.

Target distances are engineering construction inputs. The saved original body
history, not these targets, determines whether backing actually overlapped.
"""
import math
import importlib.util
from pathlib import Path
from shapely.affinity import translate
from shapely.geometry import MultiPoint,Polygon


def _axis(forward_xy):
 if not isinstance(forward_xy,(list,tuple)) or len(forward_xy)!=2:
  raise ValueError('Vehicle forward axis required')
 if any(type(v) not in (int,float) or not math.isfinite(v) for v in forward_xy):
  raise ValueError('Nonfinite vehicle forward axis')
 fx,fy=map(float,forward_xy);norm=math.hypot(fx,fy)
 if norm<0.1:raise ValueError('Zero vehicle forward axis')
 return fx/norm,fy/norm


def validate_pair(start_body_xy,forward_xy,crosswalk_polygon_xy,
                  *,over_distance_m,short_distance_m):
 """Require distinct target complete-body geometries on the same approach."""
 fx,fy=_axis(forward_xy)
 body=MultiPoint(start_body_xy).convex_hull
 crossing=Polygon(crosswalk_polygon_xy)
 if body.area<=0 or not crossing.is_valid or crossing.area<=0:
  raise ValueError('Invalid route body or crosswalk geometry')
 if body.intersects(crossing):raise ValueError('Reverse start body already overlaps crosswalk')
 for distance in (over_distance_m,short_distance_m):
  if type(distance) not in (int,float) or not math.isfinite(distance) or distance<=0:
   raise ValueError('Positive finite reverse target distance required')
 over=translate(body,xoff=-fx*over_distance_m,yoff=-fy*over_distance_m)
 short=translate(body,xoff=-fx*short_distance_m,yoff=-fy*short_distance_m)
 if not over.intersects(crossing):raise ValueError('Over target body misses crosswalk')
 if short.intersects(crossing):raise ValueError('Short target body overlaps crosswalk')
 if over_distance_m<=short_distance_m:
  raise ValueError('Over target must follow short target on same reverse route')
 return {'forward_xy':[fx,fy],
         'over_distance_m':float(over_distance_m),
         'short_distance_m':float(short_distance_m),
         'start_body_clear':True,
         'target_geometry':'constructed only; original motion unverified'}


def prepare_reviewed_pair(packet,source_root,start_body_xy,forward_xy,
                          *,over_distance_m,short_distance_m,
                          native_map_id,road_id,crosswalk_id):
 """Bind source docs and Native identities before constructing both targets."""
 spec=importlib.util.spec_from_file_location('reverse_site_review',Path(__file__).with_name('site_review.py'))
 site=importlib.util.module_from_spec(spec);spec.loader.exec_module(site)
 review=site.validate(packet,source_root,native_map_id=native_map_id,
                      road_id=road_id,crosswalk_id=crosswalk_id)
 targets=validate_pair(start_body_xy,forward_xy,packet['crosswalk_polygon_xy_m'],
                       over_distance_m=over_distance_m,
                       short_distance_m=short_distance_m)
 return {'site_review':review,'targets':targets}


class ReverseTargetController:
 def __init__(self,origin_xy,forward_xy,target_distance_m,*,stop_window_m=0.25,
              assumed_deceleration_mps2=1.5):
  if not isinstance(origin_xy,(list,tuple)) or len(origin_xy)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in origin_xy):
   raise ValueError('Finite reverse origin required')
  self.origin=tuple(map(float,origin_xy));self.forward=_axis(forward_xy)
  if type(target_distance_m) not in (int,float) or not math.isfinite(target_distance_m) or target_distance_m<=0:
   raise ValueError('Positive finite target distance required')
  if stop_window_m<=0 or not math.isfinite(stop_window_m):raise ValueError('Invalid stop window')
  if assumed_deceleration_mps2<=0 or not math.isfinite(assumed_deceleration_mps2):
   raise ValueError('Invalid assumed reverse deceleration')
  self.target=float(target_distance_m);self.window=float(stop_window_m)
  self.deceleration=float(assumed_deceleration_mps2)

 def step(self,center_xy,speed_mps):
  if not isinstance(center_xy,(list,tuple)) or len(center_xy)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in center_xy):
   raise ValueError('Finite body center required')
  if type(speed_mps) not in (int,float) or not math.isfinite(speed_mps) or speed_mps<0:
   raise ValueError('Finite nonnegative speed required')
  dx=float(center_xy[0])-self.origin[0];dy=float(center_xy[1])-self.origin[1]
  progress=-(dx*self.forward[0]+dy*self.forward[1])
  remaining=self.target-progress
  stopping_distance=float(speed_mps)**2/(2*self.deceleration)
  if remaining<=self.window+stopping_distance:
   return {'reverse':True,'throttle':0.0,'brake':1.0,
           'target_reached':remaining<=self.window,
           'reverse_progress_m':progress,'remaining_m':remaining}
  # Reduce throttle on approach; actual stopping remains a physical check.
  throttle=min(0.25,max(0.07,0.08*remaining-0.04*float(speed_mps)))
  return {'reverse':True,'throttle':throttle,'brake':0.0,'target_reached':False,
          'reverse_progress_m':progress,'remaining_m':remaining}

"""Byte-bound site context for a proposed residence-district crosswalk.

The returned check is source completeness, not a legal district or marked
crosswalk determination. Original camera pixels require separate review.
"""
import hashlib
from pathlib import Path
from shapely.geometry import Polygon


def _source(root,row,label):
 if not isinstance(row,dict) or not row.get('path') or not row.get('sha256'):
  raise ValueError('Missing '+label+' source binding')
 rel=Path(row['path'])
 if rel.is_absolute() or '..' in rel.parts:raise ValueError('Unsafe '+label+' source path')
 path=Path(root)/rel
 if not path.is_file():raise ValueError('Missing '+label+' source file')
 digest=hashlib.sha256(path.read_bytes()).hexdigest()
 if digest!=row['sha256']:raise ValueError('Stale '+label+' source hash')
 return {'path':str(rel),'sha256':digest}


def validate(packet,root,*,native_map_id,road_id,crosswalk_id):
 if not isinstance(packet,dict):raise ValueError('Site packet must be an object')
 if (packet.get('native_map_id'),packet.get('road_id'),packet.get('crosswalk_id'))!=(native_map_id,road_id,crosswalk_id):
  raise ValueError('Site packet road/crosswalk identity differs')
 if packet.get('district_kind')!='residence' or not packet.get('district_review_basis'):
  raise ValueError('Residence-district review declaration required')
 if not packet.get('crosswalk_review_basis') or not packet.get('reviewer'):
  raise ValueError('Crosswalk and reviewer basis required')
 crossing=Polygon(packet.get('crosswalk_polygon_xy_m',[]))
 roadway=Polygon(packet.get('roadway_polygon_xy_m',[]))
 if not crossing.is_valid or crossing.area<=0 or not roadway.is_valid or roadway.area<=0:
  raise ValueError('Invalid reviewed site polygons')
 if crossing.intersection(roadway).area<=0:
  raise ValueError('Crosswalk does not intersect selected roadway')
 sources={key:_source(root,packet.get(key+'_source'),key) for key in
          ('district','crosswalk_geometry','crosswalk_marking')}
 return {'format':'worker-reverse-crosswalk-site-source-check',
         'native_map_id':native_map_id,'road_id':road_id,'crosswalk_id':crosswalk_id,
         'sources':sources,'district_status':'independent review required',
         'marked_crosswalk_visibility':'unverified'}

"""Original-frame complete-body backing onto and over a sourced crosswalk."""
import hashlib,importlib.util,json,math
from pathlib import Path
from shapely.geometry import MultiPoint,Polygon
REQUIRED=('crosswalk_context.json','site_packet.json','reverse_history.jsonl','video_frames.jsonl')
def _finite(x,label):
 if isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x):raise ValueError('Missing finite '+label)
 return float(x)
def _rows(path):return [json.loads(s) for s in path.read_text().splitlines() if s.strip()]
def analyze(root:Path)->dict:
 root=Path(root);hashes={}
 for name in REQUIRED:
  p=root/name
  if not p.is_file():raise ValueError('Missing original source: '+name)
  hashes[name]=hashlib.sha256(p.read_bytes()).hexdigest()
 ctx=json.loads((root/'crosswalk_context.json').read_text())
 for key in ('native_map_id','road_id','crosswalk_id','crosswalk_geometry_source','crosswalk_camera_source','reverse_route_source','residence_district_source'):
  if not ctx.get(key):raise ValueError('Missing sourced crosswalk context: '+key)
 crosswalk=Polygon(ctx.get('crosswalk_polygon_xy_m',[]))
 if not crosswalk.is_valid or crosswalk.area<=0:raise ValueError('Invalid crosswalk polygon')
 packet=json.loads((root/'site_packet.json').read_text())
 spec=importlib.util.spec_from_file_location('reverse_saved_site_review',Path(__file__).with_name('site_review.py'))
 site=importlib.util.module_from_spec(spec);spec.loader.exec_module(site)
 review=site.validate(packet,root,native_map_id=ctx['native_map_id'],
                      road_id=ctx['road_id'],crosswalk_id=ctx['crosswalk_id'])
 if packet['crosswalk_polygon_xy_m']!=ctx['crosswalk_polygon_xy_m']:
  raise ValueError('Saved site packet crosswalk geometry differs')
 rows,frames=_rows(root/'reverse_history.jsonl'),_rows(root/'video_frames.jsonl')
 if len(rows)<3 or len(rows)!=len(frames):raise ValueError('Incomplete reverse history')
 prev=(-1,-math.inf);samples=[];prior_center=None;prior_reverse=None
 for i,(row,frame) in enumerate(zip(rows,frames)):
  fid,t=row.get('frame'),_finite(row.get('time_s'),'time')
  if type(fid) is not int or fid<=prev[0] or t<=prev[1]:raise ValueError('Nonmonotone original history')
  prev=fid,t
  if frame.get('video_frame')!=i or frame.get('carla_frame')!=fid or frame.get('time_s')!=t:raise ValueError('Original frame join failed')
  if row.get('road_id')!=ctx['road_id'] or row.get('crosswalk_id')!=ctx['crosswalk_id']:raise ValueError('Crosswalk/road identity mismatch')
  if type(row.get('native_reverse')) is not bool:raise ValueError('Missing Native reverse state')
  forward=row.get('ego_forward_xy')
  if not isinstance(forward,list) or len(forward)!=2:raise ValueError('Missing original ego heading')
  fx,fy=(_finite(v,'ego heading') for v in forward)
  norm=math.hypot(fx,fy)
  if norm<0.1:raise ValueError('Zero original ego heading')
  fx,fy=fx/norm,fy/norm
  vertices=row.get('ego_body_vertices_xy_m')
  if not isinstance(vertices,list) or len(vertices)<4:raise ValueError('Missing complete ego body')
  if row.get('body_vertices_m')!=vertices:
   raise ValueError('Pinned reverse completion body differs from measurement body')
  heading=_finite(row.get('heading_deg'),'Native heading')
  if math.cos(math.radians(heading))*fx+math.sin(math.radians(heading))*fy<0.999:
   raise ValueError('Pinned reverse completion heading differs from measurement heading')
  velocity=row.get('velocity_mps')
  if not isinstance(velocity,list) or len(velocity)<2:
   raise ValueError('Missing Native reverse velocity')
  vx,vy=(_finite(v,'Native velocity') for v in velocity[:2])
  body=MultiPoint([(_finite(v[0],'body x'),_finite(v[1],'body y')) for v in vertices]).convex_hull
  if body.area<=0:raise ValueError('Degenerate body')
  center=(body.centroid.x,body.centroid.y)
  projected_step=None if prior_center is None else (center[0]-prior_center[0])*fx+(center[1]-prior_center[1])*fy
  prior_center=center
  # Projection sign is a motion observation, not a legal distance threshold.
  backward=bool(prior_reverse is True and row['native_reverse'] and projected_step is not None and projected_step<0)
  if backward and vx*fx+vy*fy>=0:
   raise ValueError('Native velocity contradicts observed backward displacement')
  prior_reverse=row['native_reverse']
